def pre(n):
    return isinstance(n, int) and -9999 <= n <= 9999

def post(n, result):
    digit_sum_result = sum(int(digit) for digit in str(abs(n)))
    return result == digit_sum_result

def abs_value(n):
    if n < 0:
        return -n
    else:
        return n

def is_non_negative_integer(n):
    return isinstance(n, int) and n >= 0

def has_digit(digit, number):
    return (number // 10**digit) % 10 == digit
